style.css:
@-moz-document domain("trello.com") {
.ak-renderer-wrapper p,
.ak-renderer-wrapper ol,
.ak-renderer-wrapper ul,
.ak-editor-content-area p,
.ak-editor-content-area ol,
.ak-editor-content-area ul,
.ak-renderer-document p,
.ak-renderer-document ol,
.ak-renderer-document ul {
    direction: rtl;
    text-align: start;
}

.ak-renderer-wrapper ul,
.ak-editor-content-area ul,
.ak-renderer-document ul,
.ak-renderer-wrapper ol,
.ak-editor-content-area ol,
.ak-renderer-document ol {
    padding-left: 0;
    padding-right: var(--ed--list--item-counter--padding, 24px);
}

#card-back-name,
#card-back-name + textarea,
[data-testid="list-card-composer-textarea"],
[data-testid="list-card"] [data-testid="card-name"] {
    direction: rtl;
    text-align: start;
}

[data-testid="card-back-name"] > div > div > div:nth-child(2) {
    padding: 16px 16px 0 16px;
}

[data-testid="card-back-name"] > div > div > div:nth-child(3) > div:nth-child(1) {
    padding-right: 16px;
    padding-left: 16px;
}

[data-testid="card-back-name"] > div > div > div:nth-child(3) > div:nth-child(1) > div:nth-child(1) {
    padding-left: 0;
}

[data-testid="card-done-state"] {
    flex-direction: row-reverse;
}

[data-testid="card-done-state"] [role="presentation"] button {
    margin: 0px -2px 0 4px !important;
}

[data-testid="card-done-state"] > :nth-child(2) {
    transform: translateX(20px);
}

[data-testid="list-card"]:hover [data-testid="card-done-state"] > :nth-child(2) {
    transform: translateX(0);
}

[data-testid="trello-card"] > div:last-child {
    left: 2px;
    right: unset;
}

[data-testid="trello-card"] > div:last-child button {
    background-color: currentcolor;
}

[data-testid="trello-card"] > div:last-child button * {
    color: white;
}
}
